class LazyBundleLoader {constructor() {this.loadedBundles = new Set();this.loadingPromises = new Map();}async loadBundle(bundleName) {if (this.loadedBundles.has(bundleName)) {return Promise.resolve();}if (this.loadingPromises.has(bundleName)) {return this.loadingPromises.get(bundleName);}const promise = new Promise((resolve,reject) => {const script = document.createElement('script');script.src = `/assets/js/${bundleName}.min.js`;script.async = true;script.onload = () => {this.loadedBundles.add(bundleName);this.loadingPromises.delete(bundleName);resolve();};script.onerror = () => {this.loadingPromises.delete(bundleName);reject(new Error(`Failed to load bundle:${bundleName}`));};document.head.appendChild(script);});this.loadingPromises.set(bundleName,promise);return promise;}async loadExternalLibrary(libName,url) {if (this.loadedBundles.has(libName)) {return Promise.resolve();}if (this.loadingPromises.has(libName)) {return this.loadingPromises.get(libName);}const promise = new Promise((resolve,reject) => {const script = document.createElement('script');script.src = url;script.async = true;script.onload = () => {this.loadedBundles.add(libName);this.loadingPromises.delete(libName);resolve();};script.onerror = () => {this.loadingPromises.delete(libName);reject(new Error(`Failed to load library:${libName}`));};document.head.appendChild(script);});this.loadingPromises.set(libName,promise);return promise;}async loadAccessibilityFeatures() {return this.loadBundle('accessibility');}async loadInteractiveFeatures() {await Promise.all([ /* this.loadBundle('interactive'), */ this.loadExternalLibrary('fuse','https://cdn.jsdelivr.net/npm/fuse.js@6.6.2/dist/fuse.min.js') ]);}async loadFormFeatures() {return this.loadBundle('forms');}}window.LazyBundleLoader = new LazyBundleLoader();const loadA11yOnInteraction = () => {const events = ['keydown','click','focus'];const loadOnce = () => {window.LazyBundleLoader.loadAccessibilityFeatures();events.forEach(event => {document.removeEventListener(event,loadOnce,true);});};events.forEach(event => {document.addEventListener(event,loadOnce,true);});if (localStorage.getItem('accessibility-preferences')) {loadOnce();}};if (document.readyState === 'loading') {document.addEventListener('DOMContentLoaded',() => {setTimeout(() => window.LazyBundleLoader.loadInteractiveFeatures(),100);});}else {setTimeout(() => window.LazyBundleLoader.loadInteractiveFeatures(),100);}loadA11yOnInteraction();